-- EWOH realistic factory demo seed
-- Schema placeholder: public
-- Re-entrant: ON CONFLICT DO NOTHING / guarded inserts.
-- Scenario: 星辰智能制造工厂 — 新能源电池模组总装工厂
--  车间(workshop): 冲压车间 / 焊接车间 / 总装车间 / 物流仓储中心
--  区域(zone):    各车间下辖生产区
--  工位(workstation): 冲压、焊接、底盘装配、内饰装配、质量检测、物料搬运
--  人员(personnel): 装配/焊工/质检/物流/班组长/巡检/设备维护，分三班
--  设备(device): 外骨骼(EXO)、搬运AGV、视觉摄像头、UWB锚点、环境传感器、PLC
--  能力(skill/role): 重物搬运/焊接/精密装配/质量检测/设备维护/物流搬运

SELECT set_config('search_path', 'public, pg_temp', false);

